Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section KgauW.
Context {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O2Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Definition GI (M : word -> option byte) (s kel arr : Z) (rows : Z -> Z) : Prop :=
  rdn SEGS M (Z_to_bv 64 kel) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 41)) /\
  rdn SEGS M (Z_to_bv 64 (kel + 4)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 41)) /\
  rdn SEGS M (Z_to_bv 64 (kel + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 arr)) /\
  (forall i, (0 <= i < 41)%Z -> rdn SEGS M (Z_to_bv 64 (arr + 8 * i)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (rows i)))) /\
  rdn SEGS M (Z_to_bv 64 (s - 136)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 20)) /\
  rdn SEGS M (Z_to_bv 64 (s - 128)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 41)) /\
  korg M kel 20 20.

(* [comment removed for export] *)
Definition GG (C : lctx) (A A1 : AS) (s kel arr : Z) (rows : Z -> Z) : Prop :=
  (4096 <= kel)%Z /\ (kel + 24 <= alloc_top (c_vm C))%Z /\ live A1 (Z_to_bv 64 kel) = Some 24%Z /\ live A (Z_to_bv 64 kel) = None /\
  (4096 <= arr)%Z /\ (arr + 328 <= alloc_top (c_vm C))%Z /\ live A1 (Z_to_bv 64 arr) = Some 328%Z /\ live A (Z_to_bv 64 arr) = None /\
  (forall i, (0 <= i < 41)%Z -> (4096 <= rows i)%Z /\ (rows i + 164 <= alloc_top (c_vm C))%Z /\ live A1 (Z_to_bv 64 (rows i)) = Some 164%Z /\
                              live A (Z_to_bv 64 (rows i)) = None /\ live (c_A0 C) (Z_to_bv 64 (rows i)) = None /\ rows i <> arr /\ rows i <> kel) /\
  sub_live A A1 /\ (alloc_top (c_vm C) + 8192 + LSTK <= s - 144 + LSTK)%Z.

Lemma GI_rinv : forall M M' s kel arr rows ri, GI M s kel arr rows -> rinv (O2LeptKgauSegs.R_Kg s ri) M M' ->
  (0 <= kel)%Z -> (kel + 24 <= s - 160)%Z -> (0 <= arr)%Z -> (arr + 328 <= s - 160)%Z -> (s <= 2 ^ 47)%Z ->
  (ri + 164 <= kel \/ kel + 24 <= ri)%Z -> (ri + 164 <= arr \/ arr + 328 <= ri)%Z -> (ri + 164 <= s - 160)%Z ->
