Definition GREGS : list reg := [1; 2; 9; 10; 11; 12; 13; 22; 23; 27]%bv.

(* [comment removed for export] *)
Lemma kg_rows : forall (k : nat) (i : Z) fr0 fr cs regs r M C A A1 m md vm1 (s : Z) (ret : word) r0 f0 kel arr rows (S : TSet),
  Cok C -> (s <= c_top C)%Z -> (c_top C - LSTK <= s - 160)%Z -> (s <= 2 ^ 47)%Z -> (0 <= i < 41)%Z -> Z.of_nat k = (41 - i)%Z ->
  GG C A A1 s kel arr rows -> frm_zero cs ->
  W C A1 M (with_vmmaps vm1 md) -> POSTM C A s m M -> cellsZ M (frameg s ret r0 f0) -> GI M s kel arr rows ->
  getr r 2 = Z_to_bv 64 (s - 144) -> getr r 8 = Z_to_bv 64 20 -> getr r 22 = Z_to_bv 64 i -> getr r 18 = Z_to_bv 64 kel -> getr r 26 = Z_to_bv 64 41 ->
  regs_agree (fun x => In x GREGS) regs r -> (forall x : reg, In (u x) fs_list -> reg_get fr x = reg_get fr0 x) ->
  (forall fr' cs' M' r', W C A1 M' (with_vmmaps vm1 md) -> POSTM C A s m M' -> cellsZ M' (frameg s ret r0 f0) -> GI M' s kel arr rows -> frm_zero cs' ->
     (forall x : reg, In (u x) fs_list -> reg_get fr' x = reg_get fr0 x) -> getr r' 2 = Z_to_bv 64 (s - 144) -> getr r' 18 = Z_to_bv 64 kel ->
     regs_agree (fun x => In x GREGS) regs r' ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') r' (0x2d1ec : word) M' al_rom) (with_vmmaps vm1 md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr cs) r (0x2d0d8 : word) M al_rom) (with_vmmaps vm1 md)) S.
